  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `table_id` int DEFAULT NULL COMMENT '关联表ID',
  `field_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '列名',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `content` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '功能',
  `type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '类型',
  `is_key` varchar(2) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '是否主键',
  `is_null` varchar(5) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '是否可以为空',
  `is_show_add` int DEFAULT '1' COMMENT '是否显示新增',
  `is_show_edit` int DEFAULT '1' COMMENT '是否显示编辑',
  `is_show_detail` int DEFAULT '1' COMMENT '是否显示详情',
  `is_show_list` int DEFAULT '2' COMMENT '是否列表显示',
  `is_import` int DEFAULT '1' COMMENT '是否Excel导入',
  `is_export` int DEFAULT '1' COMMENT '是否导出Excel',
