v>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<script  src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}.js\"></script >\n@}\n', 'Html', '2017-11-10 09:39:34', '2017-11-10 09:38:00');
