 return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}修改\", key = \"id\" )\n    @RequestMapping(value = \"/update\")\n    @Permission\n    @ResponseBody\n    public Object update(${g.entityName}Model model) {\n        if (ToolUtil.isOneEmpty(model.getId())) {\n            throw new BussinessException(BizExceptionEnum.REQUEST_NULL);\n        }\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.updateById(model);\n        return super.SUCCESS_TIP;\n    }\n\n    /**\n     * 详情\n     */\n    @RequestMapping(value = \"/detail\")\n    @ResponseBody\n    public Object detail(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectOne(model);\n    }\n}\n', 'Java', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (22, 17, 'package ${g.codePackage}.service;\n\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\n\nimport java.util.List;\nimport java.util.Map;\n\n\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\npublic interface I${g.entityName}Service {\n\n     /**\n     * <p>\n     * 插入一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer insert(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 删除\n     * </p>\n     *\n     * @param id 主键ID\n     * @return int\n     */\n    Integer deleteById(Integer id);\n\n    /**\n     * <p>\n     * 根据 ID 修改\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer updateById(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 查询\n     * </p>\n     *\n     * @param id 主键ID\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectById(Integer id);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectOne(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 model 条件，查询总记录数\n     * </p>\n     *\n     * @param model 实体对象\n     * @return int\n     */\n    Integer selectCount(${g.entityName}Model model);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录\n     * </p>\n     *\n     * @param model 实体对象封装操作类（可以为 null）\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectList(${g.entityName}Model model);\n\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录（并翻页）\n     * </p>\n     *\n     * @param pagination 分页查询条件\n     * @param model   实体对象封装操作可以为 null）\n     * @param wrapper   SQL包装\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model,Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'C', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (23, 18, 'package ${g.codePackage}.service.impl;\n\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.dao.${g.entityName}Dao;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Service;\n\nimport java.util.List;\nimport java.util.Map;\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Service\npublic class ${g.entityName}ServiceImpl implements I${g.entityName}Service {\n\n    @Autowired\n    private ${g.entityName}Dao ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao;\n\n    @Override\n    public Integer insert(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.insert(entity);\n    }\n\n    @Override\n    public Integer deleteById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.deleteById(id);\n    }\n\n    @Override\n    public Integer updateById(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.updateById(entity);\n    }\n\n    @Override\n    public ${g.entityName}Model selectById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectById(id);\n    }\n\n    @Override\n    public ${g.entityName}Model selectOne(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectOne(entity);\n    }\n\n    @Override\n    public Integer selectCount(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectCount(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectList(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectList(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model, Wrapper<${g.entityName}Model> wrapper) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectPage(pagination,model,wrapper);\n    }\n\n}\n', 'Java', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (24, 19, 'package ${g.codePackage}.dao;\n\nimport com.baomidou.mybatisplus.mapper.BaseMapper;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\n\nimport org.apache.ibatis.annotations.Param;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${g.entityName}Dao\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Repository\npublic interface ${g.entityName}Dao extends BaseMapper<${g.entityName}Model>{\n\n    /**\n     * 统计数量\n     * @param model\n     * @return\n     */\n    Integer selectCount(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 查询列表\n     * @param model\n     * @return\n     */\n    List<${g.entityName}Model> selectList(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 分页查询信息\n     * @param pagination\n     * @param model\n     * @param wrapper\n     * @return\n     */\n    List<${g.entityName}Model> selectPage(@Param(\"p\")Pagination pagination,@Param(\"e\") ${g.entityName}Model model,@Param(\"w\") Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'Java', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (25, 20, '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n<mapper namespace=\"${g.codePackage}.dao.${g.entityName}Dao\">\n\n	<resultMap id=\"BaseResultMap\" type=\"${g.codePackage}.model.${g.entityName}Model\">\n		<%for(field in t.fields){%>\n		    <result column=\"${field.fieldName}\" property=\"${field.name}\" />\n		<%}%>\n	</resultMap>\n\n	\n	<select id=\"selectCount\" resultMap=\"BaseResultMap\">\n			select count(1) from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n	\n	<select id=\"selectList\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n\n	<select id=\"selectPage\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n			\\${w.sqlSegment}\n		</where>\n	</select>\n	\n	<sql id=\"select_content\">	\n			<%for(field in t.fields){%>\n				<if test=\"e.${field.name} != null and e.${field.name} != \'\' \">\n					AND t.${strutil.toUpperCase(field.fieldName)} = #{e.${field.name}}\n				</if>\n			<%}%>\n	</sql>\n\n</mapper>', 'Xml', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (26, 21, '@layout(\"/common/_container.html\"){\n<div class=\"row\">\n    <div class=\"col-sm-12\">\n        <div class=\"ibox float-e-margins\">\n            <div class=\"ibox-title\">\n                <h5>${g.name}管理</h5>\n            </div>\n            <div class=\"ibox-content\">\n                <div class=\"row row-lg\">\n                    <div class=\"col-sm-12\">\n                        <div class=\"row\">\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}NameCon id=\"condition\" name=\"名称\" />\n                            </div>\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}button name=\"搜索\" icon=\"fa-search\" clickFun=\"${g.entityName}.search()\"/>\n                            </div>\n                        </div>\n                        <div class=\"hidden-xs\" id=\"${g.entityName}TableToolbar\" role=\"group\">\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/add\")){\n                                <${\"#\"}button name=\"添加\" icon=\"fa-plus\" clickFun=\"${g.entityName}.openAdd${g.entityName}()\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/update\")){\n                                <${\"#\"}button name=\"修改\" icon=\"fa-plus\" clickFun=\"${g.entityName}.open${g.entityName}Detail()\" space=\"true\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/delete\")){\n                                <${\"#\"}button name=\"删除\" icon=\"fa-plus\" clickFun=\"${g.entityName}.delete()\" space=\"true\"/>\n                            @}\n                        </div>\n                        <${\"#\"}table id=\"${g.entityName}Table\"/>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<script  src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}.js\"></script >\n@}\n', 'Html', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (27, 22, '/**\n * ${g.name}管理初始化\n */\nvar ${g.entityName} = {\n    id: \"${g.entityName}Table\",	//表格id\n    seItem: null,		//选中的条目\n    table: null,\n    layerIndex: -1\n};\n\n/**\n * 初始化表格的列\n */\n${g.entityName}.initColumn = function () {\n    return [\n        {field: \'selectItem\', radio: true},\n	<%for(field in t.fields){%>\n	     {title: \'${field.chinaName}\', field: \'${field.name}\', align: \'center\', valign: \'middle\'},\n	<%}%>\n    ];\n};\n\n/**\n * 检查是否选中\n */\n${g.entityName}.check = function () {\n    var selected = $(\'#\' + this.id).bootstrapTable(\'getSelections\');\n    if(selected.length == 0){\n        Feng.info(\"请先选中表格中的某一记录！\");\n        return false;\n    }else{\n        ${g.entityName}.seItem = selected[0];\n        return true;\n    }\n};\n\n/**\n * 点击添加${g.name}\n */\n${g.entityName}.openAdd${g.entityName} = function () {\n    var index = layer.open({\n        type: 2,\n        title: \'添加${g.name}\',\n        area: [\'800px\', \'420px\'], //宽高\n        fix: false, //不固定\n        maxmin: true,\n        content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_add\'\n    });\n    this.layerIndex = index;\n};\n\n/**\n * 打开查看${g.name}详情\n */\n${g.entityName}.open${g.entityName}Detail = function () {\n    if (this.check()) {\n        var index = layer.open({\n            type: 2,\n            title: \'${g.name}详情\',\n            area: [\'800px\', \'420px\'], //宽高\n            fix: false, //不固定\n            maxmin: true,\n            content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_update/\' + ${g.entityName}.seItem.id\n        });\n        this.layerIndex = index;\n    }\n};\n\n/**\n * 删除${g.name}\n */\n${g.entityName}.delete = function () {\n    if (this.check()) {\n        var ajax = new $ax(Feng.ctxPath + \"/${strutil.toLowerCase(g.entityName)}/delete\", function (data) {\n            Feng.success(\"删除成功!\");\n            ${g.entityName}.table.refresh();\n        }, function (data) {\n            Feng.error(\"删除失败!\" + data.responseJSON.message + \"!\");\n        });\n        ajax.set(\"${strutil.toLowerCase(g.entityName)}Id\",this.seItem.id);\n        ajax.start();\n    }\n};\n\n${g.entityName}.formParams = function() {\n    var queryData = {};\n    return queryData;\n};\n\n/**\n * 查询${g.name}列表\n */\n${g.entityName}.search = function () {\n    var queryData = {};\n    queryData[\'condition\'] = $(\"#condition\").val();\n    ${g.entityName}.table.refresh({query: queryData});\n};\n\n$(function () {\n    var defaultColunms = ${g.entityName}.initColumn();\n    var table = new BSTable(${g.entityName}.id, \"/${strutil.toLowerCase(g.entityName)}/list\", defaultColunms);\n    table.setPaginationType(\"server\");\n    table.setQueryParams(${g.entityName}.formParams());\n    ${g.entityName}.table = table.init();\n});\n', 'JavaScript', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (28, 23, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.addSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (29, 24, '/**\n * 初始化${g.name}详情对话框\n */\nvar ${g.entityName}InfoDlg = {\n    ${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData : {}\n};\n\n/**\n * 清除数据\n */\n${g.entityName}InfoDlg.clearData = function() {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData = {};\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.set = function(key, val) {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData[key] = (typeof val == \"undefined\") ? $(\"#\" + key).val() : val;\n    return this;\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.get = function(key) {\n    return $(\"#\" + key).val();\n}\n\n/**\n * 关闭此对话框\n */\n${g.entityName}InfoDlg.close = function() {\n    parent.layer.close(window.parent.${g.entityName}.layerIndex);\n}\n\n/**\n * 收集数据\n */\n${g.entityName}InfoDlg.collectData = function() {\n    this.set(\'id\');\n}\n\n/**\n * 提交添加\n */\n${g.entityName}InfoDlg.addSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/add\", function(data){\n        Feng.success(\"添加成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"添加失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n/**\n * 提交修改\n */\n${g.entityName}InfoDlg.editSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/update\", function(data){\n        Feng.success(\"修改成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"修改失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n$(function() {\n\n});\n', 'JavaScript', '2018-01-26 21:56:24', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (30, 25, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\\${${strutil.toLowerCase(g.entityName)}.id}\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\" value=\"\\${${strutil.toLowerCase(g.entityName)}.${field.name}}\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.editSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-01-26 21:56:25', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (31, 26, 'package ${g.codePackage}.model;\n\nimport com.baomidou.mybatisplus.activerecord.Model;\nimport com.baomidou.mybatisplus.annotations.TableId;\nimport com.baomidou.mybatisplus.annotations.TableField;\nimport com.baomidou.mybatisplus.annotations.TableName;\nimport com.baomidou.mybatisplus.enums.IdType;\n\nimport org.apache.commons.lang3.builder.ReflectionToStringBuilder;\n\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * ${g.name}\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@TableName(\"${g.tableName}\")\npublic class ${g.entityName}Model extends Model<${g.entityName}Model> {\n\n    private static final long serialVersionUID = 1L;\n\n	\n		<%for(field in t.fields){%>\n		     /**\n		     * ${field.chinaName}\n		     * ${field.comment}\n		     */\n			<%if (field.name == \'id\') {%>\n			@TableId(value = \"id\",type = IdType.AUTO)\n			<%}else{%>\n			@TableField(value=\"${field.fieldName}\")\n			<%}%>\n			private ${field.type} ${field.name};\n		\n		<%}%>\n    \n		<%for(field in t.fields){%>\n		     /**\n		     * 获取: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public ${field.type} get${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}() {\n			return ${field.name};\n		    }\n		     /**\n		     * 设置: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public void set${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}(${field.type} ${field.name}) {\n			this.${field.name} = ${field.name};\n		    }\n		<%}%>\n       \n \n   \n\n	@Override\n	protected Serializable pkVal() {\n		return this.id;\n	}\n\n	@Override\n	public String toString() {\n		return ReflectionToStringBuilder.toString(this);\n	}\n}\n', 'Java', '2018-01-26 21:56:25', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (32, 27, 'package ${g.codePackage}.controller;\n\nimport com.baomidou.mybatisplus.mapper.EntityWrapper;\nimport com.baomidou.mybatisplus.plugins.Page;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport com.stylefeng.guns.common.annotion.Permission;\nimport com.stylefeng.guns.common.annotion.log.BussinessLog;\nimport com.stylefeng.guns.common.constant.factory.PageFactory;\nimport com.stylefeng.guns.common.constant.state.BizLogType;\nimport com.stylefeng.guns.common.controller.BaseController;\nimport com.stylefeng.guns.common.exception.BizExceptionEnum;\nimport com.stylefeng.guns.common.exception.BussinessException;\nimport com.stylefeng.guns.common.persistence.model.OperationLog;\nimport com.stylefeng.guns.core.util.ToolUtil;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\nimport javax.annotation.Resource;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * ${g.name}控制器\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Controller\n@RequestMapping(\"/${strutil.toLowerCase(g.entityName)}\")\npublic class ${g.entityName}Controller extends BaseController {\n\n    private static final Logger LOGGER = LoggerFactory.getLogger(${g.entityName}Controller.class);\n\n    private String PREFIX = \"/biz/${strutil.toLowerCase(g.entityName)}/\";\n\n    @Autowired\n    private I${g.entityName}Service ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service;\n\n    /**\n     * 跳转到首页\n     */\n    @RequestMapping(\"\")\n    public String index() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}.html\";\n    }\n\n    /**\n     * 跳转到添加\n     */\n    @RequestMapping(\"/goto_add\")\n    public String ${g.entityName}Add() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_add.html\";\n    }\n\n    /**\n     * 跳转到修改\n     */\n    @RequestMapping(\"/goto_update/{id}\")\n    public String ${g.entityName}Update(@PathVariable Integer id, Model model) {\n	model.addAttribute(\"${strutil.toLowerCase(g.entityName)}\", ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectById(id));\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_edit.html\";\n    }\n\n    /**\n     * 获取列表\n     */\n    @RequestMapping(value = \"/list\")\n    @ResponseBody\n    public Object list(${g.entityName}Model model) {\n        Page<${g.entityName}Model> page = new PageFactory<${g.entityName}Model>().defaultPage();\n        page.setRecords(${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectPage(page,model,new EntityWrapper<${g.entityName}Model>()));\n        return super.packForBT(page);\n    }\n\n\n    @BussinessLog(value = \"${g.name}新增\", key = \"companyid\" )\n    @RequestMapping(value = \"/add\")\n    @Permission\n    @ResponseBody\n    public Object add(${g.entityName}Model model) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.insert(model);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}删除\", key = \"id\" )\n    @RequestMapping(value = \"/delete\")\n    @Permission\n    @ResponseBody\n    public Object delete(Integer id) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.deleteById(id);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}修改\", key = \"id\" )\n    @RequestMapping(value = \"/update\")\n    @Permission\n    @ResponseBody\n    public Object update(${g.entityName}Model model) {\n        if (ToolUtil.isOneEmpty(model.getId())) {\n            throw new BussinessException(BizExceptionEnum.REQUEST_NULL);\n        }\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.updateById(model);\n        return super.SUCCESS_TIP;\n    }\n\n    /**\n     * 详情\n     */\n    @RequestMapping(value = \"/detail\")\n    @ResponseBody\n    public Object detail(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectOne(model);\n    }\n}\n', 'Java', '2018-01-29 14:49:25', '2017-09-14 16:40:20');
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (33, 28, 'package ${g.codePackage}.controller;\n\nimport com.baomidou.mybatisplus.mapper.EntityWrapper;\nimport com.baomidou.mybatisplus.plugins.Page;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport com.stylefeng.guns.common.annotion.Permission;\nimport com.stylefeng.guns.common.annotion.log.BussinessLog;\nimport com.stylefeng.guns.common.constant.factory.PageFactory;\nimport com.stylefeng.guns.common.constant.state.BizLogType;\nimport com.stylefeng.guns.common.controller.BaseController;\nimport com.stylefeng.guns.common.exception.BizExceptionEnum;\nimport com.stylefeng.guns.common.exception.BussinessException;\nimport com.stylefeng.guns.common.persistence.model.OperationLog;\nimport com.stylefeng.guns.core.util.ToolUtil;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\nimport javax.annotation.Resource;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * ${g.name}控制器\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Controller\n@RequestMapping(\"/${strutil.toLowerCase(g.entityName)}\")\npublic class ${g.entityName}Controller extends BaseController {\n\n    private static final Logger LOGGER = LoggerFactory.getLogger(${g.entityName}Controller.class);\n\n    private String PREFIX = \"/biz/${strutil.toLowerCase(g.entityName)}/\";\n\n    @Autowired\n    private I${g.entityName}Service ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service;\n\n    /**\n     * 跳转到首页\n     */\n    @RequestMapping(\"\")\n    public String index() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}.html\";\n    }\n\n    /**\n     * 跳转到添加\n     */\n    @RequestMapping(\"/goto_add\")\n    public String ${g.entityName}Add() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_add.html\";\n    }\n\n    /**\n     * 跳转到修改\n     */\n    @RequestMapping(\"/goto_update/{id}\")\n    public String ${g.entityName}Update(@PathVariable Integer id, Model model) {\n	model.addAttribute(\"${strutil.toLowerCase(g.entityName)}\", ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectById(id));\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_edit.html\";\n    }\n\n    /**\n     * 获取列表\n     */\n    @RequestMapping(value = \"/list\")\n    @ResponseBody\n    public Object list(${g.entityName}Model model) {\n        Page<${g.entityName}Model> page = new PageFactory<${g.entityName}Model>().defaultPage();\n        page.setRecords(${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectPage(page,model,new EntityWrapper<${g.entityName}Model>()));\n        return super.packForBT(page);\n    }\n\n\n    @BussinessLog(value = \"${g.name}新增\", key = \"companyid\" )\n    @RequestMapping(value = \"/add\")\n    @Permission\n    @ResponseBody\n    public Object add(${g.entityName}Model model) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.insert(model);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}删除\", key = \"id\" )\n    @RequestMapping(value = \"/delete\")\n    @Permission\n    @ResponseBody\n    public Object delete(Integer id) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.deleteById(id);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}修改\", key = \"id\" )\n    @RequestMapping(value = \"/update\")\n    @Permission\n    @ResponseBody\n    public Object update(${g.entityName}Model model) {\n        if (ToolUtil.isOneEmpty(model.getId())) {\n            throw new BussinessException(BizExceptionEnum.REQUEST_NULL);\n        }\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.updateById(model);\n        return super.SUCCESS_TIP;\n    }\n\n    /**\n     * 详情\n     */\n    @RequestMapping(value = \"/detail\")\n    @ResponseBody\n    public Object detail(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectOne(model);\n    }\n}\n', 'Java', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (34, 29, 'package ${g.codePackage}.service;\n\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\n\nimport java.util.List;\nimport java.util.Map;\n\n\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\npublic interface I${g.entityName}Service {\n\n     /**\n     * <p>\n     * 插入一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer insert(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 删除\n     * </p>\n     *\n     * @param id 主键ID\n     * @return int\n     */\n    Integer deleteById(Integer id);\n\n    /**\n     * <p>\n     * 根据 ID 修改\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer updateById(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 查询\n     * </p>\n     *\n     * @param id 主键ID\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectById(Integer id);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectOne(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 model 条件，查询总记录数\n     * </p>\n     *\n     * @param model 实体对象\n     * @return int\n     */\n    Integer selectCount(${g.entityName}Model model);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录\n     * </p>\n     *\n     * @param model 实体对象封装操作类（可以为 null）\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectList(${g.entityName}Model model);\n\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录（并翻页）\n     * </p>\n     *\n     * @param pagination 分页查询条件\n     * @param model   实体对象封装操作可以为 null）\n     * @param wrapper   SQL包装\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model,Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'C', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (35, 30, 'package ${g.codePackage}.service.impl;\n\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.dao.${g.entityName}Dao;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Service;\n\nimport java.util.List;\nimport java.util.Map;\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Service\npublic class ${g.entityName}ServiceImpl implements I${g.entityName}Service {\n\n    @Autowired\n    private ${g.entityName}Dao ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao;\n\n    @Override\n    public Integer insert(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.insert(entity);\n    }\n\n    @Override\n    public Integer deleteById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.deleteById(id);\n    }\n\n    @Override\n    public Integer updateById(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.updateById(entity);\n    }\n\n    @Override\n    public ${g.entityName}Model selectById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectById(id);\n    }\n\n    @Override\n    public ${g.entityName}Model selectOne(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectOne(entity);\n    }\n\n    @Override\n    public Integer selectCount(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectCount(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectList(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectList(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model, Wrapper<${g.entityName}Model> wrapper) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectPage(pagination,model,wrapper);\n    }\n\n}\n', 'Java', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (36, 31, 'package ${g.codePackage}.dao;\n\nimport com.baomidou.mybatisplus.mapper.BaseMapper;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\n\nimport org.apache.ibatis.annotations.Param;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${g.entityName}Dao\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Repository\npublic interface ${g.entityName}Dao extends BaseMapper<${g.entityName}Model>{\n\n    /**\n     * 统计数量\n     * @param model\n     * @return\n     */\n    Integer selectCount(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 查询列表\n     * @param model\n     * @return\n     */\n    List<${g.entityName}Model> selectList(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 分页查询信息\n     * @param pagination\n     * @param model\n     * @param wrapper\n     * @return\n     */\n    List<${g.entityName}Model> selectPage(@Param(\"p\")Pagination pagination,@Param(\"e\") ${g.entityName}Model model,@Param(\"w\") Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'Java', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (37, 32, '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n<mapper namespace=\"${g.codePackage}.dao.${g.entityName}Dao\">\n\n	<resultMap id=\"BaseResultMap\" type=\"${g.codePackage}.model.${g.entityName}Model\">\n		<%for(field in t.fields){%>\n		    <result column=\"${field.fieldName}\" property=\"${field.name}\" />\n		<%}%>\n	</resultMap>\n\n	\n	<select id=\"selectCount\" resultMap=\"BaseResultMap\">\n			select count(1) from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n	\n	<select id=\"selectList\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n\n	<select id=\"selectPage\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n			\\${w.sqlSegment}\n		</where>\n	</select>\n	\n	<sql id=\"select_content\">	\n			<%for(field in t.fields){%>\n				<if test=\"e.${field.name} != null and e.${field.name} != \'\' \">\n					AND t.${strutil.toUpperCase(field.fieldName)} = #{e.${field.name}}\n				</if>\n			<%}%>\n	</sql>\n\n</mapper>', 'Xml', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (38, 33, '@layout(\"/common/_container.html\"){\n<div class=\"row\">\n    <div class=\"col-sm-12\">\n        <div class=\"ibox float-e-margins\">\n            <div class=\"ibox-title\">\n                <h5>${g.name}管理</h5>\n            </div>\n            <div class=\"ibox-content\">\n                <div class=\"row row-lg\">\n                    <div class=\"col-sm-12\">\n                        <div class=\"row\">\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}NameCon id=\"condition\" name=\"名称\" />\n                            </div>\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}button name=\"搜索\" icon=\"fa-search\" clickFun=\"${g.entityName}.search()\"/>\n                            </div>\n                        </div>\n                        <div class=\"hidden-xs\" id=\"${g.entityName}TableToolbar\" role=\"group\">\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/add\")){\n                                <${\"#\"}button name=\"添加\" icon=\"fa-plus\" clickFun=\"${g.entityName}.openAdd${g.entityName}()\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/update\")){\n                                <${\"#\"}button name=\"修改\" icon=\"fa-plus\" clickFun=\"${g.entityName}.open${g.entityName}Detail()\" space=\"true\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/delete\")){\n                                <${\"#\"}button name=\"删除\" icon=\"fa-plus\" clickFun=\"${g.entityName}.delete()\" space=\"true\"/>\n                            @}\n                        </div>\n                        <${\"#\"}table id=\"${g.entityName}Table\"/>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<script  src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}.js\"></script >\n@}\n', 'Html', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (39, 34, '/**\n * ${g.name}管理初始化\n */\nvar ${g.entityName} = {\n    id: \"${g.entityName}Table\",	//表格id\n    seItem: null,		//选中的条目\n    table: null,\n    layerIndex: -1\n};\n\n/**\n * 初始化表格的列\n */\n${g.entityName}.initColumn = function () {\n    return [\n        {field: \'selectItem\', radio: true},\n	<%for(field in t.fields){%>\n	     {title: \'${field.chinaName}\', field: \'${field.name}\', align: \'center\', valign: \'middle\'},\n	<%}%>\n    ];\n};\n\n/**\n * 检查是否选中\n */\n${g.entityName}.check = function () {\n    var selected = $(\'#\' + this.id).bootstrapTable(\'getSelections\');\n    if(selected.length == 0){\n        Feng.info(\"请先选中表格中的某一记录！\");\n        return false;\n    }else{\n        ${g.entityName}.seItem = selected[0];\n        return true;\n    }\n};\n\n/**\n * 点击添加${g.name}\n */\n${g.entityName}.openAdd${g.entityName} = function () {\n    var index = layer.open({\n        type: 2,\n        title: \'添加${g.name}\',\n        area: [\'800px\', \'420px\'], //宽高\n        fix: false, //不固定\n        maxmin: true,\n        content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_add\'\n    });\n    this.layerIndex = index;\n};\n\n/**\n * 打开查看${g.name}详情\n */\n${g.entityName}.open${g.entityName}Detail = function () {\n    if (this.check()) {\n        var index = layer.open({\n            type: 2,\n            title: \'${g.name}详情\',\n            area: [\'800px\', \'420px\'], //宽高\n            fix: false, //不固定\n            maxmin: true,\n            content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_update/\' + ${g.entityName}.seItem.id\n        });\n        this.layerIndex = index;\n    }\n};\n\n/**\n * 删除${g.name}\n */\n${g.entityName}.delete = function () {\n    if (this.check()) {\n        var ajax = new $ax(Feng.ctxPath + \"/${strutil.toLowerCase(g.entityName)}/delete\", function (data) {\n            Feng.success(\"删除成功!\");\n            ${g.entityName}.table.refresh();\n        }, function (data) {\n            Feng.error(\"删除失败!\" + data.responseJSON.message + \"!\");\n        });\n        ajax.set(\"${strutil.toLowerCase(g.entityName)}Id\",this.seItem.id);\n        ajax.start();\n    }\n};\n\n${g.entityName}.formParams = function() {\n    var queryData = {};\n    return queryData;\n};\n\n/**\n * 查询${g.name}列表\n */\n${g.entityName}.search = function () {\n    var queryData = {};\n    queryData[\'condition\'] = $(\"#condition\").val();\n    ${g.entityName}.table.refresh({query: queryData});\n};\n\n$(function () {\n    var defaultColunms = ${g.entityName}.initColumn();\n    var table = new BSTable(${g.entityName}.id, \"/${strutil.toLowerCase(g.entityName)}/list\", defaultColunms);\n    table.setPaginationType(\"server\");\n    table.setQueryParams(${g.entityName}.formParams());\n    ${g.entityName}.table = table.init();\n});\n', 'JavaScript', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (40, 35, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.addSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-04-08 16:50:50', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (41, 36, '/**\n * 初始化${g.name}详情对话框\n */\nvar ${g.entityName}InfoDlg = {\n    ${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData : {}\n};\n\n/**\n * 清除数据\n */\n${g.entityName}InfoDlg.clearData = function() {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData = {};\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.set = function(key, val) {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData[key] = (typeof val == \"undefined\") ? $(\"#\" + key).val() : val;\n    return this;\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.get = function(key) {\n    return $(\"#\" + key).val();\n}\n\n/**\n * 关闭此对话框\n */\n${g.entityName}InfoDlg.close = function() {\n    parent.layer.close(window.parent.${g.entityName}.layerIndex);\n}\n\n/**\n * 收集数据\n */\n${g.entityName}InfoDlg.collectData = function() {\n    this.set(\'id\');\n}\n\n/**\n * 提交添加\n */\n${g.entityName}InfoDlg.addSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/add\", function(data){\n        Feng.success(\"添加成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"添加失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n/**\n * 提交修改\n */\n${g.entityName}InfoDlg.editSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/update\", function(data){\n        Feng.success(\"修改成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"修改失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n$(function() {\n\n});\n', 'JavaScript', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (42, 37, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\\${${strutil.toLowerCase(g.entityName)}.id}\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\" value=\"\\${${strutil.toLowerCase(g.entityName)}.${field.name}}\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.editSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (43, 38, 'package ${g.codePackage}.model;\n\nimport com.baomidou.mybatisplus.activerecord.Model;\nimport com.baomidou.mybatisplus.annotations.TableId;\nimport com.baomidou.mybatisplus.annotations.TableField;\nimport com.baomidou.mybatisplus.annotations.TableName;\nimport com.baomidou.mybatisplus.enums.IdType;\n\nimport org.apache.commons.lang3.builder.ReflectionToStringBuilder;\n\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * ${g.name}\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@TableName(\"${g.tableName}\")\npublic class ${g.entityName}Model extends Model<${g.entityName}Model> {\n\n    private static final long serialVersionUID = 1L;\n\n	\n		<%for(field in t.fields){%>\n		     /**\n		     * ${field.chinaName}\n		     * ${field.comment}\n		     */\n			<%if (field.name == \'id\') {%>\n			@TableId(value = \"id\",type = IdType.AUTO)\n			<%}else{%>\n			@TableField(value=\"${field.fieldName}\")\n			<%}%>\n			private ${field.type} ${field.name};\n		\n		<%}%>\n    \n		<%for(field in t.fields){%>\n		     /**\n		     * 获取: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public ${field.type} get${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}() {\n			return ${field.name};\n		    }\n		     /**\n		     * 设置: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public void set${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}(${field.type} ${field.name}) {\n			this.${field.name} = ${field.name};\n		    }\n		<%}%>\n       \n \n   \n\n	@Override\n	protected Serializable pkVal() {\n		return this.id;\n	}\n\n	@Override\n	public String toString() {\n		return ReflectionToStringBuilder.toString(this);\n	}\n}\n', 'Java', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (44, 39, 'package ${g.codePackage}.controller;\n\nimport com.baomidou.mybatisplus.mapper.EntityWrapper;\nimport com.baomidou.mybatisplus.plugins.Page;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport com.stylefeng.guns.common.annotion.Permission;\nimport com.stylefeng.guns.common.annotion.log.BussinessLog;\nimport com.stylefeng.guns.common.constant.factory.PageFactory;\nimport com.stylefeng.guns.common.constant.state.BizLogType;\nimport com.stylefeng.guns.common.controller.BaseController;\nimport com.stylefeng.guns.common.exception.BizExceptionEnum;\nimport com.stylefeng.guns.common.exception.BussinessException;\nimport com.stylefeng.guns.common.persistence.model.OperationLog;\nimport com.stylefeng.guns.core.util.ToolUtil;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\nimport javax.annotation.Resource;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * ${g.name}控制器\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Controller\n@RequestMapping(\"/${strutil.toLowerCase(g.entityName)}\")\npublic class ${g.entityName}Controller extends BaseController {\n\n    private static final Logger LOGGER = LoggerFactory.getLogger(${g.entityName}Controller.class);\n\n    private String PREFIX = \"/biz/${strutil.toLowerCase(g.entityName)}/\";\n\n    @Autowired\n    private I${g.entityName}Service ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service;\n\n    /**\n     * 跳转到首页\n     */\n    @RequestMapping(\"\")\n    public String index() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}.html\";\n    }\n\n    /**\n     * 跳转到添加\n     */\n    @RequestMapping(\"/goto_add\")\n    public String ${g.entityName}Add() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_add.html\";\n    }\n\n    /**\n     * 跳转到修改\n     */\n    @RequestMapping(\"/goto_update/{id}\")\n    public String ${g.entityName}Update(@PathVariable Integer id, Model model) {\n	model.addAttribute(\"${strutil.toLowerCase(g.entityName)}\", ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectById(id));\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_edit.html\";\n    }\n\n    /**\n     * 获取列表\n     */\n    @RequestMapping(value = \"/list\")\n    @ResponseBody\n    public Object list(${g.entityName}Model model) {\n        Page<${g.entityName}Model> page = new PageFactory<${g.entityName}Model>().defaultPage();\n        page.setRecords(${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectPage(page,model,new EntityWrapper<${g.entityName}Model>()));\n        return super.packForBT(page);\n    }\n\n\n    @BussinessLog(value = \"${g.name}新增\", key = \"companyid\" )\n    @RequestMapping(value = \"/add\")\n    @Permission\n    @ResponseBody\n    public Object add(${g.entityName}Model model) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.insert(model);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}删除\", key = \"id\" )\n    @RequestMapping(value = \"/delete\")\n    @Permission\n    @ResponseBody\n    public Object delete(Integer id) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.deleteById(id);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}修改\", key = \"id\" )\n    @RequestMapping(value = \"/update\")\n    @Permission\n    @ResponseBody\n    public Object update(${g.entityName}Model model) {\n        if (ToolUtil.isOneEmpty(model.getId())) {\n            throw new BussinessException(BizExceptionEnum.REQUEST_NULL);\n        }\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.updateById(model);\n        return super.SUCCESS_TIP;\n    }\n\n    /**\n     * 详情\n     */\n    @RequestMapping(value = \"/detail\")\n    @ResponseBody\n    public Object detail(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectOne(model);\n    }\n}\n', 'Java', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (45, 40, 'package ${g.codePackage}.service;\n\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\n\nimport java.util.List;\nimport java.util.Map;\n\n\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\npublic interface I${g.entityName}Service {\n\n     /**\n     * <p>\n     * 插入一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer insert(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 删除\n     * </p>\n     *\n     * @param id 主键ID\n     * @return int\n     */\n    Integer deleteById(Integer id);\n\n    /**\n     * <p>\n     * 根据 ID 修改\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return int\n     */\n    Integer updateById(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 ID 查询\n     * </p>\n     *\n     * @param id 主键ID\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectById(Integer id);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询一条记录\n     * </p>\n     *\n     * @param entity 实体对象\n     * @return ${g.entityName}Model\n     */\n    ${g.entityName}Model selectOne(${g.entityName}Model entity);\n\n    /**\n     * <p>\n     * 根据 model 条件，查询总记录数\n     * </p>\n     *\n     * @param model 实体对象\n     * @return int\n     */\n    Integer selectCount(${g.entityName}Model model);\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录\n     * </p>\n     *\n     * @param model 实体对象封装操作类（可以为 null）\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectList(${g.entityName}Model model);\n\n\n    /**\n     * <p>\n     * 根据 entity 条件，查询全部记录（并翻页）\n     * </p>\n     *\n     * @param pagination 分页查询条件\n     * @param model   实体对象封装操作可以为 null）\n     * @param wrapper   SQL包装\n     * @return List<${g.entityName}Model>\n     */\n    List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model,Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'C', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (46, 41, 'package ${g.codePackage}.service.impl;\n\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.dao.${g.entityName}Dao;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Service;\n\nimport java.util.List;\nimport java.util.Map;\n/**\n * ${g.name}Service\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Service\npublic class ${g.entityName}ServiceImpl implements I${g.entityName}Service {\n\n    @Autowired\n    private ${g.entityName}Dao ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao;\n\n    @Override\n    public Integer insert(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.insert(entity);\n    }\n\n    @Override\n    public Integer deleteById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.deleteById(id);\n    }\n\n    @Override\n    public Integer updateById(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.updateById(entity);\n    }\n\n    @Override\n    public ${g.entityName}Model selectById(Integer id) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectById(id);\n    }\n\n    @Override\n    public ${g.entityName}Model selectOne(${g.entityName}Model entity) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectOne(entity);\n    }\n\n    @Override\n    public Integer selectCount(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectCount(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectList(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectList(model);\n    }\n\n    @Override\n    public List<${g.entityName}Model> selectPage(Pagination pagination, ${g.entityName}Model model, Wrapper<${g.entityName}Model> wrapper) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Dao.selectPage(pagination,model,wrapper);\n    }\n\n}\n', 'Java', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (47, 42, 'package ${g.codePackage}.dao;\n\nimport com.baomidou.mybatisplus.mapper.BaseMapper;\nimport com.baomidou.mybatisplus.mapper.Wrapper;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport ${g.codePackage}.model.${g.entityName}Model;\n\nimport org.apache.ibatis.annotations.Param;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${g.entityName}Dao\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Repository\npublic interface ${g.entityName}Dao extends BaseMapper<${g.entityName}Model>{\n\n    /**\n     * 统计数量\n     * @param model\n     * @return\n     */\n    Integer selectCount(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 查询列表\n     * @param model\n     * @return\n     */\n    List<${g.entityName}Model> selectList(@Param(\"e\")${g.entityName}Model model);\n\n    /**\n     * 分页查询信息\n     * @param pagination\n     * @param model\n     * @param wrapper\n     * @return\n     */\n    List<${g.entityName}Model> selectPage(@Param(\"p\")Pagination pagination,@Param(\"e\") ${g.entityName}Model model,@Param(\"w\") Wrapper<${g.entityName}Model> wrapper);\n\n}\n', 'Java', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (48, 43, '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n<mapper namespace=\"${g.codePackage}.dao.${g.entityName}Dao\">\n\n	<resultMap id=\"BaseResultMap\" type=\"${g.codePackage}.model.${g.entityName}Model\">\n		<%for(field in t.fields){%>\n		    <result column=\"${field.fieldName}\" property=\"${field.name}\" />\n		<%}%>\n	</resultMap>\n\n	\n	<select id=\"selectCount\" resultMap=\"BaseResultMap\">\n			select count(1) from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n	\n	<select id=\"selectList\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n		</where>\n	</select>\n\n	<select id=\"selectPage\" resultMap=\"BaseResultMap\">\n			select * from ${strutil.toUpperCase(g.tableName)} t\n		<where>\n			<include refid=\"select_content\"/>\n			\\${w.sqlSegment}\n		</where>\n	</select>\n	\n	<sql id=\"select_content\">	\n			<%for(field in t.fields){%>\n				<if test=\"e.${field.name} != null and e.${field.name} != \'\' \">\n					AND t.${strutil.toUpperCase(field.fieldName)} = #{e.${field.name}}\n				</if>\n			<%}%>\n	</sql>\n\n</mapper>', 'Xml', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (49, 44, '@layout(\"/common/_container.html\"){\n<div class=\"row\">\n    <div class=\"col-sm-12\">\n        <div class=\"ibox float-e-margins\">\n            <div class=\"ibox-title\">\n                <h5>${g.name}管理</h5>\n            </div>\n            <div class=\"ibox-content\">\n                <div class=\"row row-lg\">\n                    <div class=\"col-sm-12\">\n                        <div class=\"row\">\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}NameCon id=\"condition\" name=\"名称\" />\n                            </div>\n                            <div class=\"col-sm-3\">\n                                <${\"#\"}button name=\"搜索\" icon=\"fa-search\" clickFun=\"${g.entityName}.search()\"/>\n                            </div>\n                        </div>\n                        <div class=\"hidden-xs\" id=\"${g.entityName}TableToolbar\" role=\"group\">\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/add\")){\n                                <${\"#\"}button name=\"添加\" icon=\"fa-plus\" clickFun=\"${g.entityName}.openAdd${g.entityName}()\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/update\")){\n                                <${\"#\"}button name=\"修改\" icon=\"fa-plus\" clickFun=\"${g.entityName}.open${g.entityName}Detail()\" space=\"true\"/>\n                            @}\n                            @if(shiro.hasPermission(\"/${strutil.toLowerCase(g.entityName)}/delete\")){\n                                <${\"#\"}button name=\"删除\" icon=\"fa-plus\" clickFun=\"${g.entityName}.delete()\" space=\"true\"/>\n                            @}\n                        </div>\n                        <${\"#\"}table id=\"${g.entityName}Table\"/>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<script  src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}.js\"></script >\n@}\n', 'Html', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (50, 45, '/**\n * ${g.name}管理初始化\n */\nvar ${g.entityName} = {\n    id: \"${g.entityName}Table\",	//表格id\n    seItem: null,		//选中的条目\n    table: null,\n    layerIndex: -1\n};\n\n/**\n * 初始化表格的列\n */\n${g.entityName}.initColumn = function () {\n    return [\n        {field: \'selectItem\', radio: true},\n	<%for(field in t.fields){%>\n	     {title: \'${field.chinaName}\', field: \'${field.name}\', align: \'center\', valign: \'middle\'},\n	<%}%>\n    ];\n};\n\n/**\n * 检查是否选中\n */\n${g.entityName}.check = function () {\n    var selected = $(\'#\' + this.id).bootstrapTable(\'getSelections\');\n    if(selected.length == 0){\n        Feng.info(\"请先选中表格中的某一记录！\");\n        return false;\n    }else{\n        ${g.entityName}.seItem = selected[0];\n        return true;\n    }\n};\n\n/**\n * 点击添加${g.name}\n */\n${g.entityName}.openAdd${g.entityName} = function () {\n    var index = layer.open({\n        type: 2,\n        title: \'添加${g.name}\',\n        area: [\'800px\', \'420px\'], //宽高\n        fix: false, //不固定\n        maxmin: true,\n        content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_add\'\n    });\n    this.layerIndex = index;\n};\n\n/**\n * 打开查看${g.name}详情\n */\n${g.entityName}.open${g.entityName}Detail = function () {\n    if (this.check()) {\n        var index = layer.open({\n            type: 2,\n            title: \'${g.name}详情\',\n            area: [\'800px\', \'420px\'], //宽高\n            fix: false, //不固定\n            maxmin: true,\n            content: Feng.ctxPath + \'/${strutil.toLowerCase(g.entityName)}/goto_update/\' + ${g.entityName}.seItem.id\n        });\n        this.layerIndex = index;\n    }\n};\n\n/**\n * 删除${g.name}\n */\n${g.entityName}.delete = function () {\n    if (this.check()) {\n        var ajax = new $ax(Feng.ctxPath + \"/${strutil.toLowerCase(g.entityName)}/delete\", function (data) {\n            Feng.success(\"删除成功!\");\n            ${g.entityName}.table.refresh();\n        }, function (data) {\n            Feng.error(\"删除失败!\" + data.responseJSON.message + \"!\");\n        });\n        ajax.set(\"${strutil.toLowerCase(g.entityName)}Id\",this.seItem.id);\n        ajax.start();\n    }\n};\n\n${g.entityName}.formParams = function() {\n    var queryData = {};\n    return queryData;\n};\n\n/**\n * 查询${g.name}列表\n */\n${g.entityName}.search = function () {\n    var queryData = {};\n    queryData[\'condition\'] = $(\"#condition\").val();\n    ${g.entityName}.table.refresh({query: queryData});\n};\n\n$(function () {\n    var defaultColunms = ${g.entityName}.initColumn();\n    var table = new BSTable(${g.entityName}.id, \"/${strutil.toLowerCase(g.entityName)}/list\", defaultColunms);\n    table.setPaginationType(\"server\");\n    table.setQueryParams(${g.entityName}.formParams());\n    ${g.entityName}.table = table.init();\n});\n', 'JavaScript', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (51, 46, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.addSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (52, 47, '/**\n * 初始化${g.name}详情对话框\n */\nvar ${g.entityName}InfoDlg = {\n    ${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData : {}\n};\n\n/**\n * 清除数据\n */\n${g.entityName}InfoDlg.clearData = function() {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData = {};\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.set = function(key, val) {\n    this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData[key] = (typeof val == \"undefined\") ? $(\"#\" + key).val() : val;\n    return this;\n}\n\n/**\n * 设置对话框中的数据\n *\n * @param key 数据的名称\n * @param val 数据的具体值\n */\n${g.entityName}InfoDlg.get = function(key) {\n    return $(\"#\" + key).val();\n}\n\n/**\n * 关闭此对话框\n */\n${g.entityName}InfoDlg.close = function() {\n    parent.layer.close(window.parent.${g.entityName}.layerIndex);\n}\n\n/**\n * 收集数据\n */\n${g.entityName}InfoDlg.collectData = function() {\n    this.set(\'id\');\n}\n\n/**\n * 提交添加\n */\n${g.entityName}InfoDlg.addSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/add\", function(data){\n        Feng.success(\"添加成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"添加失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n/**\n * 提交修改\n */\n${g.entityName}InfoDlg.editSubmit = function() {\n\n    this.clearData();\n    this.collectData();\n\n    //提交信息\n    var ajax = new $ax(Feng.ctxPath + \"/${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}/update\", function(data){\n        Feng.success(\"修改成功!\");\n        window.parent.${g.entityName}.table.refresh();\n        ${g.entityName}InfoDlg.close();\n    },function(data){\n        Feng.error(\"修改失败!\" + data.responseJSON.message + \"!\");\n    });\n    ajax.set(this.${strutil.toUpperCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}InfoData);\n    ajax.start();\n}\n\n$(function() {\n\n});\n', 'JavaScript', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (53, 48, '@layout(\"/common/_container.html\"){\n<div class=\"ibox float-e-margins\">\n    <div class=\"ibox-content\">\n        <div class=\"form-horizontal\">\n\n            <input type=\"hidden\" id=\"id\" value=\"\\${${strutil.toLowerCase(g.entityName)}.id}\">\n\n            <div class=\"row\">\n                <div class=\"col-sm-6 b-r\">\n			<%for(field in t.fields){%>\n			     <${\"#\"}input id=\"${field.name}\" name=\"${field.chinaName}\" underline=\"true\" value=\"\\${${strutil.toLowerCase(g.entityName)}.${field.name}}\"/>\n			<%}%>\n                </div>\n\n                <div class=\"col-sm-6\">\n\n                </div>\n            </div>\n\n            <div class=\"row btn-group-m-t\">\n                <div class=\"col-sm-10\">\n                    <${\"#\"}button btnCss=\"info\" name=\"提交\" id=\"ensure\" icon=\"fa-check\" clickFun=\"${g.entityName}InfoDlg.editSubmit()\"/>\n                    <${\"#\"}button btnCss=\"danger\" name=\"取消\" id=\"cancel\" icon=\"fa-eraser\" clickFun=\"${g.entityName}InfoDlg.close()\"/>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</div>\n< src=\"\\${ctxPath}/static/modular/biz/${strutil.toLowerCase(g.entityName)}/${strutil.toLowerCase(g.entityName)}_info.js\"></>\n@}\n', 'Html', '2018-04-08 16:50:51', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (54, 49, 'package ${g.codePackage}.model;\n\nimport com.baomidou.mybatisplus.activerecord.Model;\nimport com.baomidou.mybatisplus.annotations.TableId;\nimport com.baomidou.mybatisplus.annotations.TableField;\nimport com.baomidou.mybatisplus.annotations.TableName;\nimport com.baomidou.mybatisplus.enums.IdType;\n\nimport org.apache.commons.lang3.builder.ReflectionToStringBuilder;\n\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * ${g.name}\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@TableName(\"${g.tableName}\")\npublic class ${g.entityName}Model extends Model<${g.entityName}Model> {\n\n    private static final long serialVersionUID = 1L;\n\n	\n		<%for(field in t.fields){%>\n		     /**\n		     * ${field.chinaName}\n		     * ${field.comment}\n		     */\n			<%if (field.name == \'id\') {%>\n			@TableId(value = \"id\",type = IdType.AUTO)\n			<%}else{%>\n			@TableField(value=\"${field.fieldName}\")\n			<%}%>\n			private ${field.type} ${field.name};\n		\n		<%}%>\n    \n		<%for(field in t.fields){%>\n		     /**\n		     * 获取: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public ${field.type} get${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}() {\n			return ${field.name};\n		    }\n		     /**\n		     * 设置: ${field.chinaName}\n		     * ${field.comment}\n		     */\n		    public void set${strutil.toUpperCase(strutil.subStringTo (field.name,0,1))}${strutil.subString  (field.name,1)}(${field.type} ${field.name}) {\n			this.${field.name} = ${field.name};\n		    }\n		<%}%>\n       \n \n   \n\n	@Override\n	protected Serializable pkVal() {\n		return this.id;\n	}\n\n	@Override\n	public String toString() {\n		return ReflectionToStringBuilder.toString(this);\n	}\n}\n', 'Java', '2018-04-08 16:50:52', NULL);
INSERT INTO `tb_code_template_file` (`id`, `template_id`, `file`, `file_type`, `CRT_TIME`, `MDF_TIME`) VALUES (55, 50, 'package ${g.codePackage}.controller;\n\nimport com.baomidou.mybatisplus.mapper.EntityWrapper;\nimport com.baomidou.mybatisplus.plugins.Page;\nimport com.baomidou.mybatisplus.plugins.pagination.Pagination;\nimport com.stylefeng.guns.common.annotion.Permission;\nimport com.stylefeng.guns.common.annotion.log.BussinessLog;\nimport com.stylefeng.guns.common.constant.factory.PageFactory;\nimport com.stylefeng.guns.common.constant.state.BizLogType;\nimport com.stylefeng.guns.common.controller.BaseController;\nimport com.stylefeng.guns.common.exception.BizExceptionEnum;\nimport com.stylefeng.guns.common.exception.BussinessException;\nimport com.stylefeng.guns.common.persistence.model.OperationLog;\nimport com.stylefeng.guns.core.util.ToolUtil;\nimport ${g.codePackage}.model.${g.entityName}Model;\nimport ${g.codePackage}.service.I${g.entityName}Service;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseBody;\n\nimport javax.annotation.Resource;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * ${g.name}控制器\n *\n * @author ${g.author}\n * @Date ${g.date}\n */\n@Controller\n@RequestMapping(\"/${strutil.toLowerCase(g.entityName)}\")\npublic class ${g.entityName}Controller extends BaseController {\n\n    private static final Logger LOGGER = LoggerFactory.getLogger(${g.entityName}Controller.class);\n\n    private String PREFIX = \"/biz/${strutil.toLowerCase(g.entityName)}/\";\n\n    @Autowired\n    private I${g.entityName}Service ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service;\n\n    /**\n     * 跳转到首页\n     */\n    @RequestMapping(\"\")\n    public String index() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}.html\";\n    }\n\n    /**\n     * 跳转到添加\n     */\n    @RequestMapping(\"/goto_add\")\n    public String ${g.entityName}Add() {\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_add.html\";\n    }\n\n    /**\n     * 跳转到修改\n     */\n    @RequestMapping(\"/goto_update/{id}\")\n    public String ${g.entityName}Update(@PathVariable Integer id, Model model) {\n	model.addAttribute(\"${strutil.toLowerCase(g.entityName)}\", ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectById(id));\n        return PREFIX + \"${strutil.toLowerCase(g.entityName)}_edit.html\";\n    }\n\n    /**\n     * 获取列表\n     */\n    @RequestMapping(value = \"/list\")\n    @ResponseBody\n    public Object list(${g.entityName}Model model) {\n        Page<${g.entityName}Model> page = new PageFactory<${g.entityName}Model>().defaultPage();\n        page.setRecords(${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectPage(page,model,new EntityWrapper<${g.entityName}Model>()));\n        return super.packForBT(page);\n    }\n\n\n    @BussinessLog(value = \"${g.name}新增\", key = \"companyid\" )\n    @RequestMapping(value = \"/add\")\n    @Permission\n    @ResponseBody\n    public Object add(${g.entityName}Model model) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.insert(model);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}删除\", key = \"id\" )\n    @RequestMapping(value = \"/delete\")\n    @Permission\n    @ResponseBody\n    public Object delete(Integer id) {\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.deleteById(id);\n        return SUCCESS_TIP;\n    }\n\n\n    @BussinessLog(value = \"${g.name}修改\", key = \"id\" )\n    @RequestMapping(value = \"/update\")\n    @Permission\n    @ResponseBody\n    public Object update(${g.entityName}Model model) {\n        if (ToolUtil.isOneEmpty(model.getId())) {\n            throw new BussinessException(BizExceptionEnum.REQUEST_NULL);\n        }\n        ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.updateById(model);\n        return super.SUCCESS_TIP;\n    }\n\n    /**\n     * 详情\n     */\n    @RequestMapping(value = \"/detail\")\n    @ResponseBody\n    public Object detail(${g.entityName}Model model) {\n        return ${strutil.toLowerCase(strutil.subStringTo (g.entityName,0,1))}${strutil.subString  (g.entityName,1)}Service.selectOne(model);\n    }\n}\n', 'Java', '2018-04-08 16:50:52', NULL);
